/**
 * The share picture: the sample trip card, no words of ours on it, at
 * 2400 x 1260 so it stays sharp on a retina screen. Baked in as base64,
 * because R2 is off and this needs no bucket.
 *
 * To re-shoot after a design change, open /og?scale=2 in a 2400x1260
 * viewport, screenshot it, and base64 the file back into this constant.
 */
export const OG_PNG_BASE64 =
  '';

export function ogPngBytes(): Uint8Array {
  const binary = atob(OG_PNG_BASE64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes;
}
